pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // First call: succeeds on both
        c.initialize(address(0));
        // Second call: on P it reverts (invalid initialization), on M it succeeds
        bool ok;
        try c.initialize(address(0)) {
            ok = true;
        } catch {
            ok = false;
        }
        // On reference P, second call reverts -> ok == false
        // On mutant M, second call succeeds -> ok == true
        // We assert that the call failed (which is the reference behavior)
        assertTrue(!ok);
    }
}

