pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // First call to initialize succeeds
        c.initialize(address(0));
        // Second call to initialize: in P it reverts, in M it succeeds
        bool secondReverted = false;
        try c.initialize(address(0)) {
            // M allows second call
            secondReverted = false;
        } catch {
            // P reverts
            secondReverted = true;
        }
        // Now call a third time: in P it should revert (since already initialized), in M it succeeds
        bool thirdReverted = false;
        try c.initialize(address(0)) {
            thirdReverted = false;
        } catch {
            thirdReverted = true;
        }
        // In P: second call reverts (true), third call reverts (true) => secondReverted && thirdReverted is true
        // In M: second call succeeds (false), third call succeeds (false) => secondReverted && thirdReverted is false
        // So assert that secondReverted is true AND thirdReverted is true
        assertTrue(secondReverted && thirdReverted);
    }
}

