        c.initialize(address(0x1));
        // Second initialize call: reference reverts, buggy version succeeds
        bool ok = true;
        try c.initialize(address(0x1)) {
            ok = true;
        } catch {
            ok = false;
        }
        // After second call, reference reverts so _initialized is 0; buggy succeeds so _initialized is 1
