    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // First call succeeds in both P and M
        c.initialize(address(0x1234));

        // Second call: P reverts, M succeeds
        bool secondOk;
        try c.initialize(address(0x5678)) {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        // P: second call reverts => secondOk is false, version stays 0
        // M: second call succeeds => secondOk is true, version becomes 1
        // This assertion passes on P (false) and fails on M (true)
        assertTrue(c.getInitializedVersion() == 0 && !secondOk);
    }
}

