// Mock vault contract to simulate IVault
contract MockVault {
    function currentUtilizationIndex(address) external view returns (uint256) {
        return 1e27; // constant high value
    }
    function utilization(address) external view returns (uint256) {
        return 0.5e27; // 50%
    }
    function assets() external view returns (address[] memory) {}
    function totalSupplies(address) external view returns (uint256) {}
    function totalBorrows(address) external view returns (uint256) {}
    function paused(address) external view returns (bool) {}
    function availableBalance(address) external view returns (uint256) {}
    function insuranceFund() external view returns (address) {}
}

// Mock access control to bypass modifiers
contract MockAccessControl {
    mapping(bytes4 => mapping(address => mapping(address => bool))) public permissions;

    function initialize(address) external {}
    function grantAccess(bytes4 _selector, address _contract, address _address) external {
        permissions[_selector][_contract][_address] = true;
    }
    function revokeAccess(bytes4 _selector, address _contract, address _address) external {
        permissions[_selector][_contract][_address] = false;
    }
    function checkAccess(bytes4 _selector, address _contract, address _caller) external view returns (bool) {
        return permissions[_selector][_contract][_caller];
    }
    function role(bytes4, address) external pure returns (bytes32) {
        return bytes32(0);
    }
}

